1	package config
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	
10		"gopkg.in/yaml.v3"
11	)
12	
13	// Path returns the resolved config file path.
14	// Resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
15	// ~/.config/wire/config.yaml.
16	func Path() string {
17		if v := os.Getenv("WIRE_CONFIG"); v != "" {
18			return v
19		}
20		base := os.Getenv("XDG_CONFIG_HOME")
21		if base == "" {
22			home, _ := os.UserHomeDir()
23			base = filepath.Join(home, ".config")
24		}
25		return filepath.Join(base, "wire", "config.yaml")
26	}
27	
28	// WriteFile marshals cfg to YAML and atomically replaces the config file.
29	func WriteFile(cfg *Config) error {
30		path := Path()
31		data, err := yaml.Marshal(cfg)
32		if err != nil {
33			return fmt.Errorf("marshaling config: %w", err)
34		}
35		tmp := path + ".tmp"
36		if err := os.WriteFile(tmp, data, 0644); err != nil {
37			return fmt.Errorf("writing config temp file: %w", err)
38		}
39		if err := os.Rename(tmp, path); err != nil {
40			os.Remove(tmp)
41			return fmt.Errorf("renaming config file: %w", err)
42		}
43		return nil
44	}
45	
46	type Config struct {
47		Listen   string             `yaml:"listen"`
48		Backends map[string]Backend `yaml:"backends"`
49		Peers    []string           `yaml:"peers"`
50	}
51	
52	type Backend struct {
53		// Managed backend (llama-server)
54		Model     string   `yaml:"model"`      // HuggingFace ref, e.g. "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M"
55		Context   int      `yaml:"context"`    // Context window size
56		GPULayers int      `yaml:"gpu_layers"` // -ngl flag
57		Pooling   string   `yaml:"pooling"`    // "mean", "cls", "rank" — triggers --embedding flag
58		Extra     []string `yaml:"extra"`      // Additional llama-server flags
59	
60		// External backend (Ollama, OpenAI, Anthropic, etc.)
61		URL      string `yaml:"url"`      // If set, backend is external — no process management
62		APIKey   string `yaml:"api_key"`  // Bearer token or x-api-key
63		Provider string `yaml:"provider"` // "openai" (default) or "anthropic"
64	}
65	
66	// IsManaged reports whether wire manages the llama-server process for this backend.
67	func (b Backend) IsManaged() bool { return b.URL == "" }
68	
69	// IsExternal reports whether this backend is an external service.
70	func (b Backend) IsExternal() bool { return !b.IsManaged() }
71	
72	// ValidationError describes a config validation failure.
73	type ValidationError struct {
74		Field   string
75		Message string
76	}
77	
78	func (e *ValidationError) Error() string {
79		return fmt.Sprintf("config validation: %s: %s", e.Field, e.Message)
80	}
81	
82	// Load reads the config from disk, applies defaults, and validates it.
83	// Path resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
84	// ~/.config/wire/config.yaml.
85	func Load() (*Config, error) {
86		path := Path()
87	
88		data, err := os.ReadFile(path)
89		if err != nil {
90			if errors.Is(err, os.ErrNotExist) {
91				return nil, fmt.Errorf("config file not found at %s: %w", path, err)
92			}
93			return nil, fmt.Errorf("reading config %s: %w", path, err)
94		}
95	
96		cfg := new(Config)
97		dec := yaml.NewDecoder(bytes.NewReader(data))
98		dec.KnownFields(true)
99		if err := dec.Decode(cfg); err != nil {
100			return nil, fmt.Errorf("parsing config %s: %w", path, err)
101		}
102	
103		applyDefaults(cfg)
104	
105		if err := validate(cfg); err != nil {
106			return nil, err
107		}
108	
109		return cfg, nil
110	}
111	
112	func applyDefaults(cfg *Config) {
113		if cfg.Listen == "" {
114			cfg.Listen = ":8080"
115		}
116		for name, b := range cfg.Backends {
117			if b.Provider == "" {
118				b.Provider = "openai"
119			}
120			cfg.Backends[name] = b
121		}
122	}
123	
124	func validate(cfg *Config) error {
125		for name, b := range cfg.Backends {
126			switch {
127			case b.Model != "" && b.URL != "":
128				return &ValidationError{
129					Field:   "backends." + name,
130					Message: "cannot set both model and url",
131				}
132			case b.Model == "" && b.URL == "":
133				return &ValidationError{
134					Field:   "backends." + name,
135					Message: "must set either model or url",
136				}
137			}
138		}
139		return nil
140	}
141	
